```rust
#[stable(feature = "box_error", since = "1.8.0")]
// note the missing `+ ?Sized` bound.
impl<T: Error> Error for Box<T> {
    fn description(&self) -> &str {
        Error::description(&**self)
    }

    #[allow(deprecated)]
    fn cause(&self) -> Option<&dyn Error> {
